function ArticleLinkedText({ text, onCitationClick, allowedRuleKeys }) {
  const source = String(text);
  const parts = [];
  let cursor = 0;
  let safety = 0;
  while (cursor < source.length && safety < 100) {
    safety += 1;
    const remaining = source.slice(cursor);
    const candidates = [];
    const citationMatch = remaining.match(/\[(\d+)\]/);
    if (citationMatch) candidates.push({ type: "citation", index: citationMatch.index, text: citationMatch[0], citationId: citationMatch[1] });
    articleLinkRules.forEach((rule) => {
      const ruleKey = getArticleLinkRuleKey(rule);
      if (!allowedRuleKeys?.has(ruleKey)) return;
      const match = remaining.match(rule.pattern);
      if (match) candidates.push({ type: "keyword", index: match.index, text: match[0], rule });
    });
    candidates.sort((a, b) => a.index - b.index || b.text.length - a.text.length);
    if (!candidates.length) { parts.push(remaining); break; }
    const next = candidates[0];
    const absoluteIndex = cursor + next.index;
    if (absoluteIndex > cursor) parts.push(source.slice(cursor, absoluteIndex));
    if (next.type === "citation") {
      parts.push(<button key={`${next.text}-${parts.length}`} type="button" onClick={() => onCitationClick(next.citationId)} className="mx-0.5 cursor-pointer rounded px-0.5 align-baseline text-[12px] font-black text-[#7835A4] underline decoration-[#c9addb] underline-offset-2 transition hover:bg-[#f4ecf8] hover:text-[#4c1d6b]" aria-label={`Open resource ${next.citationId}`}>{next.text}</button>);
    } else {
      parts.push(<a key={`${next.text}-${parts.length}`} href={next.rule.href} className="font-black text-[#7835A4] underline decoration-[#7835A4]/35 underline-offset-2 transition hover:bg-[#f4ecf8] hover:text-[#4c1d6b]">{next.text}</a>);
    }
    cursor = absoluteIndex + next.text.length;
  }
  return parts.map((part, index) => typeof part === "string" ? <React.Fragment key={`${part}-${index}`}>{part}</React.Fragment> : part);
}

